<template><view class="page"><view class="search-box"><view class="search-field"><view class="search-icon"><view/><text/></view><input v-model="keyword" class="search-input" placeholder="输入商品名称搜索" focus maxlength="50" confirm-type="search" @input="onInput" @confirm="search"/><view v-if="keyword" class="clear" @click="clear">×</view></view><text class="cancel" @click="clear">取消</text></view><view v-if="loading" class="loading">搜索中...</view><view v-else-if="loaded&&products.length" class="grid"><view v-for="item in products" :key="item.id" class="card" @click="detail(item.id)"><view class="image-wrap"><image v-if="cover(item)" :src="cover(item)" mode="aspectFill"/><view v-else class="no-image">暂无图片</view></view><view class="info"><text>{{item.name}}</text><text class="ui-small">{{item.short_name||item.name}}</text></view></view></view><view v-else-if="loaded&&keyword" class="state"><view class="lens"/><text>未找到相关商品</text><text class="ui-small">试试其他关键词</text></view><view v-else class="state"><view class="lens"/><text>搜索 Sravx 产品</text><text class="ui-small">输入商品名称或简称快速查找</text></view></view></template>
<script>import api from '../../common/api.js';let timer;export default{data(){return{keyword:'',products:[],loading:false,loaded:false}},methods:{cover:api.productImage,onInput(){clearTimeout(timer);const word=this.keyword.trim();if(!word){this.products=[];this.loaded=false;return}timer=setTimeout(this.search,300)},async search(){const word=this.keyword.trim();if(!word)return;this.loading=true;try{this.products=api.asList(await api.getProductList({keyword:word,pageSize:50}));this.loaded=true}catch(error){this.products=[];this.loaded=true}finally{this.loading=false}},clear(){clearTimeout(timer);this.keyword='';this.products=[];this.loaded=false},detail(id){uni.navigateTo({url:`/pages/product-detail/index?id=${id}`})}}}</script>
<style>.page{min-height:100vh;background:#F4F6F8}.search-box{position:sticky;top:0;z-index:10;display:flex;align-items:center;padding:20rpx 28rpx;background:#F4F6F8}.search-field{height:72rpx;flex:1;display:flex;align-items:center;padding:0 20rpx;border-radius:36rpx;background:#e5e5ea}.search-icon{position:relative;width:28rpx;height:28rpx;margin-right:12rpx}.search-icon view{position:absolute;width:18rpx;height:18rpx;border:3rpx solid #636366;border-radius:50%}.search-icon text{position:absolute;right:0;bottom:2rpx;width:10rpx;height:3rpx;background:#636366;transform:rotate(-45deg)}.search-input{height:100%;flex:1;font-size:28rpx}.clear{width:36rpx;height:36rpx;line-height:36rpx;text-align:center;border-radius:50%;background:#c7c7cc;color:#fff;font-size:26rpx}.cancel{margin-left:20rpx;padding:0 8rpx;color:#636366;font-size:28rpx}.grid{display:flex;flex-wrap:wrap;gap:20rpx;padding:16rpx 24rpx}.card{width:calc(50% - 10rpx);overflow:hidden;border-radius:20rpx;background:#fff}.image-wrap{position:relative;width:100%;height:0;padding-top:100%;background:#e5e5ea}.image-wrap image,.no-image{position:absolute;top:0;left:0;width:100%;height:100%}.no-image{display:flex;align-items:center;justify-content:center;color:#636366;font-size:24rpx}.info{padding:16rpx 20rpx 20rpx;display:flex;flex-direction:column;gap:6rpx}.info text{font-size:28rpx;font-weight:500;line-height:1.3}.info .ui-small,.state .ui-small{font-size:24rpx;color:#636366}.loading{padding-top:200rpx;text-align:center;color:#636366;font-size:28rpx}.state{padding-top:180rpx;display:flex;flex-direction:column;align-items:center;gap:10rpx}.state text{font-size:30rpx;font-weight:600}.lens{position:relative;width:56rpx;height:56rpx;margin-bottom:24rpx;border:5rpx solid #636366;border-radius:50%}.lens::after{content:'';position:absolute;right:-26rpx;bottom:-12rpx;width:30rpx;height:5rpx;border-radius:4rpx;background:#636366;transform:rotate(45deg)}</style>
